SELECT SUBSTRING_INDEX(c.path, ' > ', 1) AS dept, COUNT(DISTINCT r.order_item_id) * 1.0 / COUNT(DISTINCT oi.order_item_id) AS return_rate FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN product_variants v ON v.variant_id = oi.variant_id JOIN products p ON p.product_id = v.product_id JOIN categories c ON c.category_id = p.category_id LEFT JOIN returns r ON r.order_item_id = oi.order_item_id WHERE NOT o.is_deleted AND o.status IN ('delivered', 'returned') AND CAST(o.order_at AS DATE) BETWEEN DATE '2026-01-01' AND DATE '2026-03-31' AND SUBSTRING_INDEX(c.path, ' > ', 1) IN ('Fashion', 'Electronics') GROUP BY 1
